229	  - [ ] `seed-b-backend.Api/Controllers/CartController.cs` um drei Actions erweitern und die bestehende `AddItem`-Action auf einen gemeinsamen `MapToDto`-Helper umstellen (entfernt die bisherige Inline-Duplizierung der DTO-Zuordnung):
230	    ```csharp
231	    using Microsoft.AspNetCore.Mvc;
232	    using seed_b_backend.Api.Application;
233	    using seed_b_backend.Api.Controllers.Dtos;
234	
235	    namespace seed_b_backend.Api.Controllers;
236	
237	    [ApiController]
238	    [Route("api/cart")]
239	    public class CartController(CartService cartService) : ControllerBase
240	    {
241	        [HttpPost("items")]
242	        public async Task<ActionResult<CartDto>> AddItem(
243	            [FromHeader(Name = "X-Cart-Id")] string? cartId,
244	            [FromBody] AddCartItemRequest request,
245	            CancellationToken ct = default)
246	        {
247	            var parsedCartId = Guid.TryParse(cartId, out var parsed) ? parsed : (Guid?)null;
248	
249	            var result = await cartService.AddItemAsync(parsedCartId, request.ProductId, request.SupplierId, request.Quantity, ct);
250	            if (result is null)
251	            {
252	                return NotFound();
253	            }
254	
255	            return Ok(MapToDto(result));
256	        }
257	
258	        [HttpGet]
259	        public async Task<ActionResult<CartDto>> GetCart(
260	            [FromHeader(Name = "X-Cart-Id")] string? cartId,
261	            CancellationToken ct = default)
262	        {
263	            var parsedCartId = Guid.TryParse(cartId, out var parsed) ? parsed : (Guid?)null;
264	            var result = await cartService.GetCartAsync(parsedCartId, ct);
265	            return Ok(MapToDto(result));
266	        }
267	
268	        [HttpPatch("items/{productId}/{supplierId}")]
269	        public async Task<ActionResult<CartDto>> UpdateItemQuantity(
270	            [FromHeader(Name = "X-Cart-Id")] string? cartId,
271	            string productId,
272	            string supplierId,
273	            [FromBody] UpdateCartItemQuantityRequest request,
274	            CancellationToken ct = default)
275	        {
276	            var parsedCartId = Guid.TryParse(cartId, out var parsed) ? parsed : (Guid?)null;
277	            if (parsedCartId is null)
278	            {
279	                return NotFound();
280	            }
281	
282	            var result = await cartService.UpdateItemQuantityAsync(parsedCartId.Value, productId, supplierId, request.Quantity, ct);
283	            return result.Status switch
284	            {
285	                CartMutationStatus.ItemNotFound => NotFound(),
286	                CartMutationStatus.OfferGone => Conflict(new { error = "Angebot nicht mehr verfügbar" }),
287	                _ => Ok(MapToDto(result.Cart!))
288	            };
289	        }
290	
291	        [HttpDelete("items/{productId}/{supplierId}")]
292	        public async Task<ActionResult<CartDto>> RemoveItem(
293	            [FromHeader(Name = "X-Cart-Id")] string? cartId,
294	            string productId,
295	            string supplierId,
296	            CancellationToken ct = default)
297	        {
298	            var parsedCartId = Guid.TryParse(cartId, out var parsed) ? parsed : (Guid?)null;
299	            var result = await cartService.RemoveItemAsync(parsedCartId, productId, supplierId, ct);
300	            return Ok(MapToDto(result));
301	        }
302	
303	        private static CartDto MapToDto(CartResult result) => new()
304	        {
305	            CartId = result.CartId,
306	            TotalPrice = result.TotalPrice,
307	            Items = result.Items
308	                .Select(l => new CartItemDto
309	                {
310	                    ProductId = l.ProductId,
311	                    ProductName = l.ProductName,
312	                    SupplierId = l.SupplierId,
313	                    SupplierName = l.SupplierName,
314	                    Quantity = l.Quantity,
315	                    UnitPrice = l.UnitPrice,
316	                    LineTotal = l.UnitPrice * l.Quantity
317	                })
318	                .ToList()
319	        };
320	    }
321	    ```
322	    - **`PATCH` bei fehlendem/ungültigem Header liefert direkt `404`, ohne `CartService` aufzurufen:** Es gibt keinen sinnvollen „leeren Warenkorb"-Fall für eine Mengenänderung — anders als `GetCart`/`RemoveItem` (AC 2/7), die absichtlich fehlertolerant sind.
323	    - **`Conflict(new { error = "..." })` statt eines bloßen Statuscodes (AC 5):** Liefert ein JSON-Objekt `{ "error": "Angebot nicht mehr verfügbar" }` — das Frontend zeigt diesen Text direkt an (siehe Task 5), identisches Prinzip zu FR14s künftiger strukturierter Fehlerantwort (Epic 4), hier für den ersten tatsächlichen Anwendungsfall vorweggenommen.
324	
325	- [ ] **Task 3: Backend-Tests (xUnit v3) für `CartService`-Erweiterungen** (AC: 1, 2, 3, 4, 5, 6, 7)
326	  - [ ] `seed-b-backend.Tests/Application/CartServiceTests.cs` erweitern — bestehende Test-Fixture (`Constructor`, Kategorie `CC`/Unterkategorie `SC1`/Produkt `PC1`/Lieferanten `LC1`,`LC2`/Angebote `10.00`/`12.00`) unverändert wiederverwenden, folgende `[Fact]`-Methoden ergänzen:
327	    ```csharp
328	    [Fact]
329	    public async Task GetCartAsync_NoCartId_ReturnsEmptyCartWithoutError()
330	    {
331	        var result = await _service.GetCartAsync(null);
332	
333	        Assert.Null(result.CartId);
334	        Assert.Empty(result.Items);
335	        Assert.Equal(0m, result.TotalPrice);
