348	    public async Task GetCartAsync_WithItems_ReturnsNamesPricesAndTotals()
349	    {
350	        var added = await _service.AddItemAsync(null, "PC1", "LC1", 3);
351	
352	        var result = await _service.GetCartAsync(added!.CartId);
353	
354	        Assert.Equal(added.CartId, result.CartId);
355	        Assert.Single(result.Items);
356	        Assert.Equal("Warenkorbprodukt", result.Items[0].ProductName);
357	        Assert.Equal("Lieferant Eins", result.Items[0].SupplierName);
358	        Assert.Equal(30.00m, result.TotalPrice);
359	    }
360	
361	    [Fact]
362	    public async Task GetCartAsync_ItemWithRemovedOffer_ExcludesLineFromResult()
363	    {
364	        var added = await _service.AddItemAsync(null, "PC1", "LC1", 1);
365	        var offer = await _context.Offers.SingleAsync(o => o.ProductId == "PC1" && o.SupplierId == "LC1");
366	        _context.Offers.Remove(offer);
367	        await _context.SaveChangesAsync();
368	
369	        var result = await _service.GetCartAsync(added!.CartId);
370	
371	        Assert.Empty(result.Items);
372	        Assert.Equal(0m, result.TotalPrice);
