374	
375	    [Fact]
376	    public async Task UpdateItemQuantityAsync_ValidQuantity_UpdatesAndReturnsRecalculatedCart()
377	    {
378	        var added = await _service.AddItemAsync(null, "PC1", "LC1", 1);
379	
380	        var result = await _service.UpdateItemQuantityAsync(added!.CartId, "PC1", "LC1", 5);
381	
